def search_substr(fullText, searchText, allowOverlap=True):
    if searchText == '':
        return 0
    count = 0
    i = 0
    while i <= len(fullText) - len(searchText):
        if fullText[i:i+len(searchText)] == searchText:
            count += 1
            if not allowOverlap:
                i += len(searchText)
            else:
                i += 1
        else:
            i += 1
    return count
